import type { TurretConfig, TurretScheduleConfig } from "./TurretConfig";

export interface BossConfigData{
    id:string;
    name:string;
    maxHp:number;
    collisionRadius: number;

    /**
     * 阶段 HP 阈值。stageHpRatios[i] 是"进入阶段 i+1"的 HP 比例。
     * 长度 = 阶段数 - 1。例如 [0.7, 0.35] 表示：
     *   - HP ≤ 70% 进入阶段 1
     *   - HP ≤ 35% 进入阶段 2
     * 初始阶段是 0，不写阈值。
     */
    stageHpRatios: number[];

    turrets: TurretConfig[];

    /** 炮台开火调度。不配置 = 默认 volley（各自独立计时） */
    turretSchedule?: TurretScheduleConfig;
}


